proc routeVaultModule[T](instance: T, bare: string, params: openArray[byte]): Result[seq[byte], InvocationFailure] =
  mixin `exchange`, `fetch`, `peek`, `store`
  let request = ?kitValidator().checkedRequest(bare, params)
  if bare == "exchange":
    var typed = fromChecked(VaultExchangeRequest, request)
    wipe(request)
    var response = `exchange`(instance, typed)
    wipeTyped(typed)
    if response.isErr:
      result = err(response.error)
      wipeError(response)
      return
    result = encodedResponse(encode(response.get))
    wipeTyped(response.get)
    return
  if bare == "fetch":
    var response = `fetch`(instance, fromChecked(VaultFetchRequest, request))
    if response.isErr:
      result = err(response.error)
      wipeError(response)
      return
    result = encodedResponse(encode(response.get))
    wipeTyped(response.get)
    return
  if bare == "peek":
    let response = ?`peek`(instance, fromChecked(VaultPeekRequest, request))
    return encodedResponse(encode(response))
  if bare == "store":
    var typed = fromChecked(VaultStoreRequest, request)
    wipe(request)
    var response = `store`(instance, typed)
    wipeTyped(typed)
    if response.isErr:
      result = err(response.error)
      wipeError(response)
      return
    result = encodedResponse(encode(response.get))
    return
  discard request
  err(failure(ecMethodNotFound, "unknown method " & bare))

